class BaseModelFormMetaclassTest(TestCase):
    def test_model_form_metaclass_new(self):
        # Test handling of fields and exclude
        class TestForm(forms.ModelForm):
            class Meta:
                model = Author
                fields = ['name']

        self.assertIn('name', TestForm.base_fields)
        # Assuming Author has 'bio' field which is excluded
        self.assertNotIn('bio', TestForm.base_fields)

        # Test declared fields override
        class CustomField(forms.CharField):
            pass

        class OverrideForm(forms.ModelForm):
            name = CustomField()

            class Meta:
                model = Author
                fields = ['name']

        self.assertIsInstance(OverrideForm.base_fields['name'], CustomField)

        # Test fields=__all__
        class AllFieldsForm(forms.ModelForm):
            class Meta:
                model = Author
                fields = '__all__'

        # Check all model fields are present (excluding non-editable)
        for field in Author._meta.fields:
            if field.editable:
                self.assertIn(field.name, AllFieldsForm.base_fields)

        # Test exclude
        class ExcludeForm(forms.ModelForm):
            class Meta:
                model = Author
                exclude = ['bio']

        self.assertNotIn('bio', ExcludeForm.base_fields)

        # Test ImproperlyConfigured if no fields/exclude
        with self.assertRaises(ImproperlyConfigured):
            class NoFieldsForm(forms.ModelForm):
                class Meta:
                    model = Author

        # Test string fields/exclude raises TypeError
        with self.assertRaises(TypeError):
            class StringFieldsForm(forms.ModelForm):
                class Meta:
                    model = Author
                    fields = 'name'

        with self.assertRaises(TypeError):
            class StringExcludeForm(forms.ModelForm):
                class Meta:
                    model = Author
                    exclude = 'name'

        # Test invalid field in fields
        with self.assertRaises(FieldError):
            class InvalidFieldForm(forms.ModelForm):
                class Meta:
                    model = Author
                    fields = ['invalid_field']

        # Test ALL_FIELDS sentinel conversion to None
        class AllFieldsMetaForm(forms.ModelForm):
            class Meta:
                model = Author
                fields = '__all__'

        self.assertIsNone(AllFieldsMetaForm._meta.fields)
