            def setup_class(cls, request):
                values.append('fixture_setup')
            @classmethod
            def teardown_class(cls):
                values.append('teardown')
            def test_one(self):
                assert 'fixture_setup' in values
                assert 'setup_class' not in values
        def test_after():
