class TestFindParametrizedScope:
    def test_find_parametrized_scope(self):
        from _pytest.python import _find_parametrized_scope

        class MockFixtureDef:
            def __init__(self, scope):
                self.scope = scope
                self.baseid = ""

        # Case: indirect=False → returns 'function'
        assert _find_parametrized_scope(['arg1'], {}, indirect=False) == 'function'

        # Case: indirect=True but no arg2fixturedefs → returns 'function'
        assert _find_parametrized_scope(['arg1'], {}, indirect=True) == 'function'

        # Case: session scope
        arg2fixturedefs = {
            'arg1': [MockFixtureDef('session')]
        }
        assert _find_parametrized_scope(['arg1'], arg2fixturedefs, indirect=True) == 'session'

        # Case: module and session fixtures → returns 'session'
        arg2fixturedefs = {
            'arg1': [MockFixtureDef('module')],
            'arg2': [MockFixtureDef('session')],
        }
        assert _find_parametrized_scope(['arg1', 'arg2'], arg2fixturedefs, indirect=True) == 'session'

        # Case: function and class → returns 'class'
        arg2fixturedefs = {
            'arg1': [MockFixtureDef('function')],
            'arg2': [MockFixtureDef('class')],
        }
        assert _find_parametrized_scope(['arg1', 'arg2'], arg2fixturedefs, indirect=True) == 'class'

        # Case: module and function → returns 'module'
        arg2fixturedefs = {
            'arg1': [MockFixtureDef('module')],
            'arg2': [MockFixtureDef('function')],
        }
        assert _find_parametrized_scope(['arg1', 'arg2'], arg2fixturedefs, indirect=True) == 'module'

        # Case: all scopes present → returns 'session'
        arg2fixturedefs = {
            'arg1': [MockFixtureDef('session')],
            'arg2': [MockFixtureDef('module')],
            'arg3': [MockFixtureDef('class')],
            'arg4': [MockFixtureDef('function')],
        }
        assert _find_parametrized_scope(['arg1','arg2','arg3','arg4'], arg2fixturedefs, indirect=True) == 'session'

        # Case: indirect list with subset → returns 'module'
        arg2fixturedefs = {
            'arg1': [MockFixtureDef('module')],
            'arg2': [MockFixtureDef('function')],
        }
        assert _find_parametrized_scope(['arg1', 'arg2'], arg2fixturedefs, indirect=['arg1']) == 'module'

        # Case: no fixtures found → function
        arg2fixturedefs = {}
        assert _find_parametrized_scope(['arg1'], arg2fixturedefs, indirect=True) == 'function'
