    sub.join("conftest.py").write(
        textwrap.dedent(
            """\
            import pytest

            @pytest.fixture
            def sub_fixture():
                return "sub"
            """
        )
    )
    # Create test file to trigger collection
    sub.join("test_fixture.py").write("def test_dummy(): pass")
    # Run pytest --fixtures
    result = testdir.runpytest("--fixtures")
    # Check output contains both fixtures
    result.stdout.fnmatch_lines([
        "*fixtures defined from pkg.__init__*package_fixture*",
        "*fixtures defined from pkg.sub.conftest*sub_fixture*",
