from django.utils.decorators import _multi_decorate

class MultiDecorateFunctionTests(SimpleTestCase):
    def test_multi_decorate_applies_single_decorator(self):
        """_multi_decorate correctly applies a single decorator."""
        def dec(func):
            def wrapper(x):
                return func(x) + 1
            return wrapper

        def method(x):
            """Original method docstring."""
            return x

        wrapped = _multi_decorate(dec, method)
        self.assertEqual(wrapped(5), 6)
        self.assertEqual(wrapped.__name__, 'method')
        self.assertEqual(wrapped.__doc__, 'Original method docstring.')

    def test_multi_decorate_applies_multiple_decorators_in_order(self):
        """_multi_decorate applies decorators in the correct reverse order."""
        def dec1(func):
            def wrapper(x):
                return func(x) * 10
            return wrapper

        def dec2(func):
            def wrapper(x):
                return func(x) + 1
            return wrapper

        def method(x):
            return x

        wrapped = _multi_decorate([dec1, dec2], method)
        # dec2 runs first, then dec1: 5 → 5+1=6 → 6*10=60
        self.assertEqual(wrapped(5), 60)

    def test_multi_decorate_copies_decorator_attributes(self):
        """Attributes from each decorator are copied to the wrapped method."""
        def dec_a(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            wrapper.attr_a = 'a'
            return wrapper

        def dec_b(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            wrapper.attr_b = 'b'
            return wrapper

        def method():
            pass

        wrapped = _multi_decorate([dec_a, dec_b], method)
        self.assertTrue(hasattr(wrapped, 'attr_a'))
        self.assertEqual(wrapped.attr_a, 'a')
        self.assertTrue(hasattr(wrapped, 'attr_b'))
        self.assertEqual(wrapped.attr_b, 'b')

    def test_multi_decorate_preserves_method_attributes(self):
        """_multi_decorate preserves the method's original attributes."""
        def method():
            """Original docstring."""
            pass
        method.custom_attr = 42

        wrapped = _multi_decorate(lambda f: lambda: None, method)
        self.assertEqual(wrapped.__doc__, 'Original docstring.')
        self.assertEqual(wrapped.__name__, 'method')
        self.assertEqual(getattr(wrapped, 'custom_attr', None), 42)
