def test_compile_dictionary():
    # Test valid function translation with fixed arguments
    custom_translations = {
        'MyFunc[x_, y_]': 'Add(x, y)',
    }
    parser = MathematicaParser(additional_translations=custom_translations)
    expr1 = parser.parse('MyFunc[2, 3]')
    assert expr1 == 2 + 3

    # Test valid function translation with variable-length arguments
    custom_translations_varargs = {
        'VarArgsFunc[*x]': 'Mul(*x)',
    }
    parser_varargs = MathematicaParser(additional_translations=custom_translations_varargs)
    expr2 = parser_varargs.parse('VarArgsFunc[2, 3, 4]')
    assert expr2 == 2*3*4

    # Test invalid function form (mismatched brackets)
    invalid_translations = {
        'Invalid[x': 'SomeFunc(x)',
    }
    with raises(ValueError):
        MathematicaParser(additional_translations=invalid_translations)

    # Test invalid function name (starts with number)
    invalid_name_translations = {
        '1InvalidFunc[x_]': 'Func(x)',
    }
    with raises(ValueError):
        MathematicaParser(additional_translations=invalid_name_translations)

    # Test function with special characters in argument names
    special_char_translations = {
        'SpecialFunc[α_, β_]': 'Add(α, β)',
    }
    parser_special = MathematicaParser(additional_translations=special_char_translations)
    expr3 = parser_special.parse('SpecialFunc[5, 7]')
    assert expr3 == 5 + 7

    # Test whitespace handling in function forms
    whitespace_translations = {
        '  WhiteSpaceFunc  [  x_  ,  y_  ]  ': 'Add(x, y)',
    }
    parser_whitespace = MathematicaParser(additional_translations=whitespace_translations)
    expr4 = parser_whitespace.parse('WhiteSpaceFunc[3, 4]')
    assert expr4 == 3 + 4
