    def test_save_update_instance(self):
        class TestModel(models.Model):
            name = models.CharField(max_length=100)
            class Meta:
                app_label = 'check_framework'

        instance = TestModel.objects.create(name='Test')
        instance.name = 'Updated'
        instance.save()
        self.assertEqual(TestModel.objects.get().name, 'Updated')

    def test_save_with_parent_models(self):
        class ParentModel(models.Model):
            parent_field = models.CharField(max_length=100)
            class Meta:
                app_label = 'check_framework'

        class ChildModel(ParentModel):
            child_field = models.CharField(max_length=100)

        instance = ChildModel(parent_field='Parent', child_field='Child')
        instance.save()
        parent = ParentModel.objects.get()
        child = ChildModel.objects.get()
        self.assertEqual(parent.parent_field, 'Parent')
        self.assertEqual(child.child_field, 'Child')
        self.assertEqual(instance.pk, parent.pk)

    def test_save_signals(self):
        pre_save_called = False
        post_save_called = False

        def pre_save_handler(sender, **kwargs):
            nonlocal pre_save_called
            pre_save_called = True

        def post_save_handler(sender, **kwargs):
            nonlocal post_save_called
            post_save_called = True

        pre_save.connect(pre_save_handler)
        post_save.connect(post_save_handler)

        class TestModel(models.Model):
            name = models.CharField(max_length=100)
            class Meta:
                app_label = 'check_framework'

        try:
            instance = TestModel(name='Test')
            instance.save()
            self.assertTrue(pre_save_called)
            self.assertTrue(post_save_called)
        finally:
            pre_save.disconnect(pre_save_handler)
            post_save.disconnect(post_save_handler)
