class FieldsForModelTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.c1 = Category.objects.create(name='Entertainment', slug='entertainment', url='entertainment')
        cls.c2 = Category.objects.create(name='A test', slug='test', url='test')

    def test_fields_for_model_includes_excludes(self):
        # Test include and exclude parameters
        include_fields = ['name', 'slug']
        exclude_fields = ['url']
        fields = fields_for_model(Category, fields=include_fields, exclude=exclude_fields)
        for field in include_fields:
            with self.subTest('Check included field', field=field):
                self.assertIn(field, fields)
        for field in exclude_fields:
            with self.subTest('Check excluded field', field=field):
                self.assertNotIn(field, fields)

        # Test exclude takes precedence over fields
        fields = fields_for_model(Category, fields=['name'], exclude=['name'])
        self.assertEqual(len(fields), 0)

    def test_fields_for_model_applies_widget(self):
        from django.forms.widgets import Textarea
        widgets = {'name': Textarea}
        fields = fields_for_model(Category, widgets=widgets)
        self.assertIsInstance(fields['name'].widget, Textarea)

    def test_fields_for_model_labels_and_help_texts(self):
        labels = {'name': 'Custom Label'}
        help_texts = {'name': 'Enter category name'}
        fields = fields_for_model(Category, labels=labels, help_texts=help_texts)
        self.assertEqual(fields['name'].label, 'Custom Label')
        self.assertEqual(fields['name'].help_text, 'Enter category name')

    def test_fields_for_model_error_messages(self):
        error_messages = {'name': {'max_length': 'Too long'}}
        fields = fields_for_model(Category, error_messages=error_messages)
        self.assertEqual(fields['name'].error_messages['max_length'], 'Too long')

    def test_fields_for_model_field_classes(self):
        from django.forms import CharField
        class CustomCharField(CharField):
            pass
        field_classes = {'name': CustomCharField}
        fields = fields_for_model(Category, field_classes=field_classes)
        self.assertIsInstance(fields['name'], CustomCharField)
