        """Test that skipped tests via marks report the correct line number in the output."""
        p = testdir.makepyfile('''
            import pytest

            @pytest.mark.skip(reason="skip reason")
            def test_skip_here():
                assert False, "Should be skipped"
        ''')
        result = testdir.runpytest("-rs")
        # The line number should point to the test function's definition line (line 4)
        result.stdout.fnmatch_lines([
            "SKIPPED [*] test_skip_mark_line_reporting.py:4: skip reason"
        ])
