def test_init_subclass_wraps_defined_methods():
    """Test that __init_subclass__ wraps methods defined in the subclass."""
    pd = pytest.importorskip("pandas")

    class Parent:
        def transform(self, X):
            return np.array([[1, 2], [3, 4]])

    class ChildWithOwnTransform(_SetOutputMixin, Parent):
        auto_wrap_output_keys = ("transform",)
        def get_feature_names_out(self, input_features=None):
            return ["a", "b"]

        def transform(self, X):
            return np.array([[1, 2], [3, 4]])

    child = ChildWithOwnTransform().set_output(transform="pandas")
    X_trans = child.transform(None)
    assert isinstance(X_trans, pd.DataFrame)
    assert_array_equal(X_trans.columns, ["a", "b"])

    class ChildInheritsTransform(_SetOutputMixin, Parent):
        auto_wrap_output_keys = ("transform",)
        def get_feature_names_out(self, input_features=None):
            return ["a", "b"]

    child2 = ChildInheritsTransform().set_output(transform="pandas")
    X_trans2 = child2.transform(None)
    assert isinstance(X_trans2, np.ndarray)
