import pytest
from astropy.wcs import _parse_keysel
import _wcs

def test_parse_keysel_none():
    assert _parse_keysel(None) == -1

def test_parse_keysel_image():
    assert _parse_keysel(['image']) == _wcs.WCSHDR_IMGHEAD

def test_parse_keysel_binary():
    assert _parse_keysel(['binary']) == _wcs.WCSHDR_BIMGARR

def test_parse_keysel_pixel():
    assert _parse_keysel(['pixel']) == _wcs.WCSHDR_PIXLIST

def test_parse_keysel_combinations():
    flags = _parse_keysel(['image', 'binary', 'pixel'])
    expected = _wcs.WCSHDR_IMGHEAD | _wcs.WCSHDR_BIMGARR | _wcs.WCSHDR_PIXLIST
    assert flags == expected

def test_parse_keysel_case_insensitive():
    assert _parse_keysel(['Image', 'BINARY', 'PixEl']) == _parse_keysel(['image', 'binary', 'pixel'])

def test_parse_keysel_invalid():
    with pytest.raises(ValueError) as exc_info:
        _parse_keysel(['invalid'])
    assert 'keysel must be a list of' in str(exc_info.value)

def test_parse_keysel_mixed_valid_invalid():
    with pytest.raises(ValueError) as exc_info:
        _parse_keysel(['image', 'invalid'])
    assert 'keysel must be a list of' in str(exc_info.value)

def test_parse_keysel_empty_list():
    assert _parse_keysel([]) == 0
