class TestFormsetFormKwargsDynamicWithEmpty(SimpleTestCase):
    def test_get_form_kwargs_with_empty_index(self):
        class CustomForm(Form):
            def __init__(self, *args, custom_kwarg, **kwargs):
                self.custom_kwarg = custom_kwarg
                super().__init__(*args, **kwargs)

        class DynamicFormSet(BaseFormSet):
            def get_form_kwargs(self, index):
                if index is None:
                    return {'custom_kwarg': 'empty'}
                return {'custom_kwarg': index}

        FormSet = formset_factory(CustomForm, formset=DynamicFormSet, extra=1)
        formset = FormSet()

        # Check regular forms have index-based kwargs
        self.assertEqual(formset.forms[0].custom_kwarg, 0)
        # Check empty_form uses kwargs from index=None
        self.assertEqual(formset.empty_form.custom_kwarg, 'empty')
